namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;
    private const int WelcomeFiveCents = 500;
    private const int SummerTenCapCents = 1_500;

    public static int LoyaltyPartCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(subtotalCents * RatePercent(tier) / 100, CapCents);

    public static int DiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyCents = LoyaltyPartCents(subtotalCents, tier);
        var promoCents = PromoPartCents(subtotalCents - loyaltyCents, promoCode);
        return Math.Min(loyaltyCents + promoCents, subtotalCents);
    }

    private static int PromoPartCents(int remainingCents, string? promoCode)
    {
        if (string.Equals(promoCode, "WELCOME5", StringComparison.OrdinalIgnoreCase))
        {
            return WelcomeFiveCents;
        }

        if (string.Equals(promoCode, "SUMMER10", StringComparison.OrdinalIgnoreCase))
        {
            return Math.Min(remainingCents / 10, SummerTenCapCents);
        }

        return 0;
    }

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier))
    };
}
